// The Parity page charts the trails port's convergence over time, straight out
// of the stats DB the host's nightly sync writes (see statssync.go for the cron
// that fills it). Every merged PR's CI runs `api:compare`, `api:compare
// --privates` and `test:compare` per package and the sync parses those job logs
// into three tables of the same shape:
//
//	api_compare_stats           matched/total/percent + misplaced, missing
//	api_compare_privates_stats  matched/total/percent + missing
//	test_compare_stats          matched/total/percent + misplaced, skipped
//
// None of them carry a timestamp — they key on merge_commit_sha/pr_number — so
// the time axis comes from joining pull_requests.merged_at. ringo only reads;
// nothing here writes to the DB.

// statsDBPath returns the trails stats DB. Override with STATS_DB; the default
// sits next to the sync log (see statsSyncLogPath).
func statsDBPath() string {
	home, _ := os.UserHomeDir()
	return envOr("STATS_DB", home+"/github/blazetrailsdev/stats.db")
}

// parityMetric is one measure the page can chart: a comparison run's headline
// parity, or a ratio derived from another column of the same table.
//
// Num/Den name the columns whose ratio is the parity, defaulting to the
// matched/total pair every compare run writes. Sub is subtracted from Num,
// which is how the advisory assertion checks become parities of their own:
// mapped tests are the denominator, and the mismatching ones come off the top.
type parityMetric struct {
	Key   string   // URL/query value
	Label string   // shown in the metric picker
	Table string   // stats table
	Num   string   // numerator column; "" means "matched"
	Den   string   // denominator column; "" means "total"
	Sub   string   // subtracted from the numerator; "" means nothing is
	Gaps  []string // extra count columns, charted as the "gaps" series
}

func (m parityMetric) num() string {
	if m.Num == "" {
		return "matched"
	}
	return m.Num
}

func (m parityMetric) den() string {
	if m.Den == "" {
		return "total"
	}
	return m.Den
}

// native reports whether this metric is the run's own headline number, in which
// case the percent column CI wrote is authoritative and gets read rather than
// recomputed. A derived metric has no percent column of its own.
func (m parityMetric) native() bool {
	return m.num() == "matched" && m.den() == "total" && m.Sub == ""
}

// cols is every column the metric reads, in the order queryParity selects them.
func (m parityMetric) cols() []string {
	out := []string{m.num(), m.den()}
	if m.Sub != "" {
		out = append(out, m.Sub)
	}
	if m.native() {
		out = append(out, "percent")
	}
	return out
}

// parityMetrics is the fixed set the page offers, in picker order. Adding a new
// comparison run means adding its table here — the handlers and the page are
// driven entirely off this list.
var parityMetrics = []parityMetric{
	{Key: "api", Label: "api:compare", Table: "api_compare_stats", Gaps: []string{"misplaced", "missing"}},
	{Key: "api_privates", Label: "api:compare --privates", Table: "api_compare_privates_stats", Gaps: []string{"missing"}},
	// assertion_count_mismatch / assertion_kind_mismatch are advisory counters on
	// mapped tests, so they belong beside misplaced and skipped as gaps rather
	// than as metrics of their own — the tests percent doesn't move with them.
	{Key: "test", Label: "test:compare", Table: "test_compare_stats",
		Gaps: []string{"misplaced", "skipped", "assertion_count_mismatch", "assertion_kind_mismatch"}},
	// The same run's other two ratios. Files says how much of the test tree has
	// been mapped at all, which moves well ahead of the tests inside it; the
	// assertion pair says how much of what IS mapped agrees with the Ruby.
	// They are separate metrics rather than gaps because they are parities —
	// out of mapped tests, not out of the reference surface.
	{Key: "test_files", Label: "test:compare files", Table: "test_compare_stats",
		Num: "files_mapped", Den: "files_total"},
	{Key: "test_assert_count", Label: "test:compare assertion counts", Table: "test_compare_stats",
		Num: "matched", Den: "matched", Sub: "assertion_count_mismatch"},
	{Key: "test_assert_kind", Label: "test:compare assertion kinds", Table: "test_compare_stats",
		Num: "matched", Den: "matched", Sub: "assertion_kind_mismatch"},
	// The two advisory call checks the `--calls` run prints. compare.ts tallies
	// them across packages and prints one grand total each, so these tables hold
	// a single package, "all" — the picker shows one chip and the chart one line.
	{Key: "calls", Label: "api:compare --calls", Table: "api_calls_stats", Gaps: []string{"mismatched"}},
	{Key: "call_args", Label: "calls:args", Table: "api_call_args_stats", Gaps: []string{"mismatched"}},
}

func lookupParityMetric(key string) (parityMetric, bool) {
	for _, m := range parityMetrics {
		if m.Key == key {
			return m, true
		}
	}
	return parityMetric{}, false
}

// parityPoint is one package's standing at the end of one day: the numbers from
// the last PR merged that day. A day with no merges has no point, so the line
// simply spans the gap rather than dropping to zero.
type parityPoint struct {
	Date    string         `json:"date"` // YYYY-MM-DD
	PR      int            `json:"pr"`   // the PR the numbers came from
	Percent float64        `json:"percent"`
	Matched int            `json:"matched"`
	Total   int            `json:"total"`
	Gaps    map[string]int `json:"gaps,omitempty"`
}

// paritySeries is one line: one package's standing under one metric. The page
// charts several runs at once, so a series has to say which run it came from —
// the same package appears once per selected metric.
type paritySeries struct {
	Metric  string        `json:"metric"`
	Package string        `json:"package"`
	Points  []parityPoint `json:"points"`
}

// Parity serves the parity charts. It holds no state beyond a short-lived cache
// of the package list — the stats DB only changes once a day, when the host
// sync cron runs, but the queries are cheap enough to run per request.
type Parity struct {
	mu sync.Mutex
	// packages is keyed by metric: the calls tables hold only the synthetic
	// "all" package, so a single union list would offer chips that chart
	// nothing on every other metric.
	packages map[string][]string
	fetched  map[string]time.Time
}

// parityPackagesTTL bounds how long the cached package list is reused. The list
// only grows when a new package starts being compared, i.e. at most once a day.
const parityPackagesTTL = 10 * time.Minute

// openStatsDB opens the stats DB read-only. It is in WAL mode and the host's
// sync cron writes to it, so the connection must tolerate a concurrent writer:
// busy_timeout makes a locked read wait rather than fail immediately.
func openStatsDB() (*sql.DB, error) {
	path := statsDBPath()
	if _, err := os.Stat(path); err != nil {
		return nil, fmt.Errorf("stats DB not readable at %s (set STATS_DB, and bind-mount it into the container): %w", path, err)
	}
	db, err := sql.Open("sqlite", "file:"+path+"?mode=ro&_pragma=busy_timeout(5000)")
	if err != nil {
		return nil, err
	}
	// One connection is plenty for a page that loads on demand, and it keeps
	// the WAL reader footprint to a single -shm registration.
	db.SetMaxOpenConns(1)
	return db, nil
}

// listParityPackages returns every package name in one metric's table, sorted.
// This is the canonical order the page assigns colors from, so it must be
// stable across requests — hence the sort.
//
// A table the sync hasn't created yet (a metric whose CI step is newer than the
// DB) reads as "no packages" rather than an error, so one missing table can't
// take the whole page down.
func (p *Parity) listParityPackages(db *sql.DB, m parityMetric) ([]string, error) {
	p.mu.Lock()
	if cached, ok := p.packages[m.Key]; ok && time.Since(p.fetched[m.Key]) < parityPackagesTTL {
		out := append([]string(nil), cached...)
		p.mu.Unlock()
		return out, nil
	}
	p.mu.Unlock()

	rows, err := db.Query("SELECT DISTINCT package FROM " + m.Table)
	if err != nil {
		if strings.Contains(err.Error(), "no such table") {
			return []string{}, nil
		}
		return nil, err
	}
	var out []string
	for rows.Next() {
		var pkg string
		if err := rows.Scan(&pkg); err != nil {
			rows.Close()
			return nil, err
		}
		if pkg != "" {
			out = append(out, pkg)
		}
	}
	err = rows.Err()
	rows.Close()
	if err != nil {
		return nil, err
	}
	sort.Strings(out)

	p.mu.Lock()
	if p.packages == nil {
		p.packages, p.fetched = map[string][]string{}, map[string]time.Time{}
	}
	p.packages[m.Key], p.fetched[m.Key] = out, time.Now()
	p.mu.Unlock()
	return append([]string(nil), out...), nil
}

// availableGaps narrows a metric's gap list to the columns its table actually
// has. The stats DB is written by a cron in another repo, so ringo can be
// deployed before (or after) a migration that adds a counter — charting a gap
// column that isn't there yet would fail the whole query and take a working
// metric down with it. Unknown columns are simply not offered.
func availableGaps(db *sql.DB, m parityMetric) []string {
	if len(m.Gaps) == 0 {
		return nil
	}
	have := tableColumns(db, m.Table)
	out := make([]string, 0, len(m.Gaps))
	for _, g := range m.Gaps {
		if have[g] {
			out = append(out, g)
		}
	}
	return out
}

// metricAvailable reports whether the DB has every column this metric reads.
// The stats DB is filled by a cron in another repo, so ringo can be deployed
// against a schema that predates a metric — offering a run whose column is not
// there yet would fail the query and take the whole page down with it.
func metricAvailable(db *sql.DB, m parityMetric) bool {
	have := tableColumns(db, m.Table)
	if len(have) == 0 {
		return false
	}
	for _, c := range m.cols() {
		if !have[c] {
			return false
		}
	}
	return true
}

// tableColumns is the column set of one stats table, empty when the table does
// not exist.
func tableColumns(db *sql.DB, table string) map[string]bool {
	rows, err := db.Query("SELECT name FROM pragma_table_info(?)", table)
	if err != nil {
		return nil
	}
	defer rows.Close()
	have := map[string]bool{}
	for rows.Next() {
		var col string
		if err := rows.Scan(&col); err != nil {
			return nil
		}
		have[col] = true
	}
	return have
}

// parityMaxPackages caps how many packages one request may chart. The page
// paints each package in a fixed categorical slot and there are eight slots; a
// ninth series would have to reuse a color, so it is refused instead.
const parityMaxPackages = 8

// queryParity returns one series per requested package: the day-end standing of
// each, oldest day first.
//
// The daily rollup is a plain GROUP BY leaning on SQLite's documented bare-column
// rule — with a single max() in the select list, the other bare columns come from
// the row that produced the max. So each (day, package) row is the last PR merged
// that day, which is exactly "where the package stood at end of day".
func queryParity(db *sql.DB, m parityMetric, gaps []string, packages []string, since string) ([]paritySeries, error) {
	if len(packages) == 0 {
		return []paritySeries{}, nil
	}
	mcols := m.cols()
	cols := "s.pr_number"
	for _, c := range mcols {
		cols += ", s." + c
	}
	for _, g := range gaps {
		cols += ", s." + g
	}
	placeholders := strings.TrimSuffix(strings.Repeat("?,", len(packages)), ",")
	q := fmt.Sprintf(`
		SELECT substr(p.merged_at, 1, 10) AS day, s.package, MAX(p.merged_at), %s
		FROM %s s
		JOIN pull_requests p ON p.number = s.pr_number
		WHERE p.merged_at IS NOT NULL AND p.merged_at != ''
		  AND p.merged_at >= ?
		  AND s.package IN (%s)
		GROUP BY day, s.package
		ORDER BY day`, cols, m.Table, placeholders)

	args := make([]any, 0, len(packages)+1)
	args = append(args, since)
	for _, pkg := range packages {
		args = append(args, pkg)
	}
	rows, err := db.Query(q, args...)
	if err != nil {
		return nil, err
	}
	defer rows.Close()

	byPkg := map[string]*paritySeries{}
	for rows.Next() {
		var (
			day, pkg, mergedAt string
			pt                 parityPoint
			vals               = make([]sql.NullFloat64, len(mcols))
			gapVals            = make([]sql.NullInt64, len(gaps))
		)
		dest := []any{&day, &pkg, &mergedAt, &pt.PR}
		for i := range vals {
			dest = append(dest, &vals[i])
		}
		for i := range gapVals {
			dest = append(dest, &gapVals[i])
		}
		if err := rows.Scan(dest...); err != nil {
			return nil, err
		}
		pt.Date = day
		pt.Matched, pt.Total = int(vals[0].Float64), int(vals[1].Float64)
		if m.Sub != "" {
			pt.Matched -= int(vals[2].Float64)
		}
		if m.native() {
			pt.Percent = vals[len(vals)-1].Float64
		} else if pt.Total > 0 {
			// One decimal, matching what CI writes into the percent column, so a
			// derived line and a native one read at the same precision.
			pt.Percent = float64(int(1000*float64(pt.Matched)/float64(pt.Total)+0.5)) / 10
		}
		if len(gaps) > 0 {
			pt.Gaps = make(map[string]int, len(gaps))
			for i, g := range gaps {
				pt.Gaps[g] = int(gapVals[i].Int64)
			}
		}
		s := byPkg[pkg]
		if s == nil {
			s = &paritySeries{Package: pkg}
			byPkg[pkg] = s
		}
		s.Points = append(s.Points, pt)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}

	// Return series in the caller's requested order so the page's color
	// assignment doesn't depend on which packages happened to have data.
	out := make([]paritySeries, 0, len(byPkg))
	for _, pkg := range packages {
		if s := byPkg[pkg]; s != nil {
			out = append(out, *s)
		}
	}
	return out, nil
}

// paritySince turns a ?days= window into the merged_at lower bound the query
// wants. days=0 (or "all") means no bound.
func paritySince(days string) string {
	if days == "" || days == "all" {
		return ""
	}
	n, err := strconv.Atoi(days)
	if err != nil || n <= 0 {
		return ""
	}
	return time.Now().UTC().AddDate(0, 0, -n).Format("2006-01-02")
}

// HandleParityData serves the JSON behind /parity.
//
//	?metrics=api,test                which comparison runs to chart, in picker
//	                                 order (default api). ?metric= is the older
//	                                 single-run spelling and still works.
//	?packages=a,b,c                  up to parityMaxPackages (default: none, the
//	                                 page always names what it wants)
//	?days=30|90|365|all              merged_at window (default all)
//
// Every selected run is charted at once rather than one behind a picker: the
// questions people actually ask of this page ("are the tests keeping up with the
// API surface?") compare two runs on one axis. The response carries the union of
// the runs' package lists plus each run's own gap columns, so the page can draw
// its whole picker from one round trip.
func (p *Parity) HandleParityData(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Content-Type", "application/json")
	w.Header().Set("Cache-Control", "no-store, no-cache, must-revalidate")
	fail := func(msg string) {
		json.NewEncoder(w).Encode(map[string]any{"error": msg})
	}

	q := r.URL.Query()
	var selected []parityMetric
	for _, key := range splitCSV(q.Get("metrics") + "," + q.Get("metric")) {
		m, ok := lookupParityMetric(key)
		if !ok {
			fail("unknown metric " + key)
			return
		}
		if !hasMetric(selected, m.Key) {
			selected = append(selected, m)
		}
	}
	if len(selected) == 0 {
		selected = []parityMetric{parityMetrics[0]}
	}

	packages := splitCSV(q.Get("packages"))
	if len(packages) > parityMaxPackages {
		fail(fmt.Sprintf("at most %d packages at a time", parityMaxPackages))
		return
	}

	db, err := openStatsDB()
	if err != nil {
		fail(err.Error())
		return
	}
	defer db.Close()

	// The picker only offers runs this DB can actually chart, and only charts
	// the selected ones that survive that test.
	offered := make([]map[string]any, 0, len(parityMetrics))
	gapsByMetric := map[string][]string{}
	available := map[string]bool{}
	for _, m := range parityMetrics {
		if !metricAvailable(db, m) {
			continue
		}
		available[m.Key] = true
		gapsByMetric[m.Key] = availableGaps(db, m)
		offered = append(offered, map[string]any{
			"key": m.Key, "label": m.Label, "gaps": gapsByMetric[m.Key],
		})
	}

	// The package list is the union over the selected runs, in canonical order:
	// the page assigns a color per package from it, and a package charted under
	// one run must keep its color under the others.
	var all []string
	seen := map[string]bool{}
	perMetric := map[string]map[string]bool{}
	for _, m := range selected {
		if !available[m.Key] {
			continue
		}
		list, err := p.listParityPackages(db, m)
		if err != nil {
			fail("package list: " + err.Error())
			return
		}
		known := map[string]bool{}
		for _, pkg := range list {
			known[pkg] = true
			if !seen[pkg] {
				seen[pkg] = true
				all = append(all, pkg)
			}
		}
		perMetric[m.Key] = known
	}
	sort.Strings(all)

	// A package no selected run measures is dropped rather than failing the
	// request — a bookmarked URL can name packages from another run, and the
	// calls tables hold only the synthetic "all". The page says what it ignored.
	var kept, unknown []string
	for _, pkg := range packages {
		charted := false
		for _, m := range selected {
			if perMetric[m.Key][pkg] {
				charted = true
				break
			}
		}
		if charted {
			kept = append(kept, pkg)
		} else {
			unknown = append(unknown, pkg)
		}
	}

	series := []paritySeries{}
	for _, m := range selected {
		if !available[m.Key] {
			continue
		}
		var want []string
		for _, pkg := range kept {
			if perMetric[m.Key][pkg] {
				want = append(want, pkg)
			}
		}
		got, err := queryParity(db, m, gapsByMetric[m.Key], want, paritySince(q.Get("days")))
		if err != nil {
			fail("query: " + err.Error())
			return
		}
		for i := range got {
			got[i].Metric = m.Key
			series = append(series, got[i])
		}
	}

	keys := make([]string, 0, len(selected))
	for _, m := range selected {
		keys = append(keys, m.Key)
	}
	json.NewEncoder(w).Encode(map[string]any{
		"metrics_selected": keys,
		"gaps_by_metric":   gapsByMetric,
		"metrics":          offered,
		"packages":         all,
		"unknown_packages": unknown,
		"max_packages":     parityMaxPackages,
		"series":           series,
	})
}

// splitCSV is the query-parameter list form the page uses: comma separated,
// trimmed, blanks dropped.
func splitCSV(v string) []string {
	var out []string
	for _, s := range strings.Split(v, ",") {
		if s = strings.TrimSpace(s); s != "" {
			out = append(out, s)
		}
	}
	return out
}

func hasMetric(list []parityMetric, key string) bool {
	for _, m := range list {
		if m.Key == key {
			return true
		}
	}
	return false
}

// HandleParityPage serves the standalone Parity page HTML.
func (p *Parity) HandleParityPage(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Content-Type", "text/html; charset=utf-8")
	w.Header().Set("Cache-Control", "no-store, no-cache, must-revalidate")
	fmt.Fprint(w, parityHTML)
}
